/* ---- Question card header: clean, no internal labels ---- */
.qcard .qhead{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 2px}
.qcard .qnum{font-size:12px;font-weight:850;letter-spacing:.08em;color:#8fc6ff}
.qcard .qkind{margin-left:auto;font-size:11.5px;font-weight:700;line-height:1.3;padding:4px 11px;border-radius:99px;border:1px solid rgba(80,150,235,.38);background:rgba(60,130,230,.1);color:#9dcaff;white-space:nowrap}
.qcard .qhead+.qstem,.qcard .qhead+.qwarn+.qstem{margin-top:8px}
.phone.light .rs.qb .qnum{color:#2774b7!important}
.phone.light .rs.qb .qkind{color:#2d6da8!important;background:#edf5fc!important;border-color:#d2e3f1!important}
/* Old header pieces stay hidden if any other script still renders them */
.qcard .qtop .qid,.qcard .qtop .qstat,.qcard .qtop .qtag,.qcard>.qtopic{display:none!important}
.qcard.qzin .qtop .qid{display:none!important}

/* Nelson cover badge in the Pediatrics collection chooser */
.ped-collection-card .ped-collection-avatar.ped-avatar-nelson{width:92px;height:92px;min-width:92px;flex:0 0 92px;border:0;background:transparent;box-shadow:none;clip-path:none;overflow:visible}
.ped-collection-card .ped-collection-avatar.ped-avatar-nelson img{object-fit:contain;clip-path:none;border-radius:0;filter:drop-shadow(0 4px 12px rgba(40,110,220,.35))}
.qfilters .dd:only-child{grid-column:1/-1;width:100%;max-width:none}

