/* Update "Later": the pending update is remembered and offered again in Settings → Downloads & updates. */
var PENDING_KEY='shbace_update_later',pending=null;
function savePending(p){pending=p;try{localStorage.setItem(PENDING_KEY,JSON.stringify({files:p.files.length,bytes:p.bytes,t:Date.now()}))}catch(e){}}
function clearPending(){pending=null;try{localStorage.removeItem(PENDING_KEY)}catch(e){}}
window.shbaceUpdates={
 installed:function(){return standalone()},
 info:function(){
  if(pending)return {files:pending.files.length,bytes:pending.bytes,text:fmtBytes(pending.bytes)};
  var r=null;try{r=JSON.parse(localStorage.getItem(PENDING_KEY)||'null')}catch(e){}
  return r&&r.files?{files:r.files,bytes:r.bytes,text:fmtBytes(r.bytes)}:null;
 },
 check:function(go){
  if(!standalone())return Promise.resolve('not-installed');
  if(go&&pending){var p0=pending;clearPending();showPlanNeeded(p0);runPlan();return Promise.resolve('running')}
  return decide().then(function(res){
   if(!res||res.kind==='none'){clearPending();return 'current'}
   if(res.kind==='prompt'){
    if(go){clearPending();showPlanNeeded(res.plan);runPlan();return 'running'}
    savePending(res.plan);return 'available';
   }
   showPlanNeeded(res.plan);return 'setup';
  }).catch(function(){return 'offline'});
 }
};
